/**
 * Native Crouch_Walk sampled from skeletal-boss-crouch-walk.blend, not the GLB's
 * jaw/grab validation clip. 109 evaluated bones include driven fingers and cloth.
 * One 2.4 s cycle, sampled at 25 Hz. Absolute bone-local transforms in the approved
 * GLB rest basis: Blender root converted by -90 degrees around X; child transforms
 * are parent-pose inverse times child pose. Positions are original 32 m asset units;
 * the model wrapper supplies the existing 20 / 32 scale. Quaternions are XYZW.
 * Native +Z travel (6 m/cycle) is stripped; crouch offset, bob and sway are retained.
 * The final sample repeats the first for an exact seam. Bone names use Three's
 * sanitized GLTF names (periods removed). Interpolate positions and slerp rotations.
 */
export interface CrouchWalkFrame {
  readonly t: number;
  readonly positions: readonly number[];
  readonly quaternions: readonly number[];
}

export interface CrouchWalkData {
  readonly duration: number;
  /** Original-asset meters per cycle; multiply by the model's uniform scale. */
  readonly stride: number;
  readonly bones: readonly string[];
  readonly frames: readonly CrouchWalkFrame[];
}

